import{splitGroundPixels}from'./foreground-split.js';
/** Local draft editor. Does not change the project or discard any existing art. */
export function groundSplitEditor(api,original,{current,onPreview,onChoose}){
 const $=api.$,host=$('#authoritySplitter');let job=0,draft=null,mask=Array(256).fill(0),paint=false,erase=false,source=null,floor=null,candidate=null;
 const canvas=$('#authorityPixelMask'),ctx=canvas.getContext('2d');
 const read=async tile=>{const im=await api.image(tile.a),c=document.createElement('canvas');c.width=c.height=16;const x=c.getContext('2d');x.imageSmoothingEnabled=false;x.drawImage(im,tile.sx,tile.sy,tile.size,tile.size,0,0,16,16);return x.getImageData(0,0,16,16).data;};
 function draw(){if(!source)return;const c=document.createElement('canvas');c.width=c.height=16;const x=c.getContext('2d'),d=x.createImageData(16,16);d.data.set(source);x.putImageData(d,0,0);ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,256,256);ctx.drawImage(c,0,0,256,256);ctx.fillStyle='rgba(255,0,180,.5)';for(let i=0;i<256;i++)if(mask[i])ctx.fillRect(i%16*16,Math.floor(i/16)*16,16,16);ctx.strokeStyle='rgba(0,0,0,.25)';for(let i=0;i<=16;i++){ctx.beginPath();ctx.moveTo(i*16,0);ctx.lineTo(i*16,256);ctx.moveTo(0,i*16);ctx.lineTo(256,i*16);ctx.stroke();}}
 function update(){draw();draft=null;const count=mask.filter(Boolean).length,visible=source&&mask.some((v,i)=>v&&source[i*4+3]);$('#authoritySplitCount').textContent=count+' pixels selected. '+(!floor?'Choose a floor tile below.':'Floor selected. Preview before saving.');$('#authorityUseSplit').disabled=!visible||!floor;const fc=$('#authorityFloorPreview'),fx=fc.getContext('2d');fx.clearRect(0,0,64,64);if(floor){const t=document.createElement('canvas');t.width=t.height=16;const tx=t.getContext('2d'),d=tx.createImageData(16,16);d.data.set(floor);tx.putImageData(d,0,0);fx.imageSmoothingEnabled=false;fx.drawImage(t,0,0,64,64);}if(!visible||!floor)return;const parts=splitGroundPixels(source,floor,mask),uid=globalThis.crypto.randomUUID?.()||Date.now()+'-'+Math.random(),asset=(data,part)=>{const c=document.createElement('canvas');c.width=c.height=16;const x=c.getContext('2d'),d=x.createImageData(16,16);d.data.set(data);x.putImageData(d,0,0);return{id:'foreground-split-'+uid+'-'+part,name:'Separated '+part,width:16,height:16,tileSize:16,data:c.toDataURL('image/png'),category:'custom'};};draft={choice:'split-ground',split:{version:1,mask:[...mask],floorSource:structuredClone(candidate),lowerAsset:asset(parts.lower,'floor'),upperAsset:asset(parts.upper,'foreground')}};}
 const mark=e=>{if(!source)return;const b=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-b.left)*16/b.width),y=Math.floor((e.clientY-b.top)*16/b.height);if(x<0||y<0||x>=16||y>=16)return;mask[y*16+x]=erase?0:1;update();e.preventDefault();};
 canvas.addEventListener('pointerdown',e=>{paint=true;erase=$('#authorityErasePixels').checked;canvas.setPointerCapture?.(e.pointerId);mark(e);});canvas.addEventListener('pointermove',e=>{if(paint)mark(e);});for(const type of ['pointerup','pointercancel'])canvas.addEventListener(type,()=>{paint=false;});
 $('#authorityClearPixels').onclick=()=>{mask.fill(0);update();};$('#authorityAllPixels').onclick=()=>{mask.fill(1);update();};
 $('#authorityPreviewSplit').onclick=()=>{if(draft)onPreview(draft);else api.toast('Select pixels and a floor tile first.');};$('#authorityUseSplit').onclick=()=>{if(draft)onChoose(draft);};
 const selectFloor=async()=>{const token=job,value=$('#authorityFloorTile').value;floor=null;candidate=null;if(value){const c=current(),map=original.maps.find(m=>m.id===c.mapId),i=+value.slice(1),t=map.layers.ground[i];try{const pixels=await read(t);if(token!==job)return;floor=pixels;candidate={mapId:map.id,x:i%map.width,y:Math.floor(i/map.width),tile:structuredClone(t)};}catch(e){api.toast('Could not load floor: '+e.message);}}update();};$('#authorityFloorTile').onchange=selectFloor;$('#authorityFloorCoordinates').onclick=()=>{const c=current(),m=original.maps.find(m=>m.id===c.mapId),x=Number($('#authorityFloorX').value),y=Number($('#authorityFloorY').value);if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=m.width||y>=m.height||!m.layers.ground[y*m.width+x]){api.toast('Choose coordinates containing ground artwork.');return;}const value='i'+(y*m.width+x),select=$('#authorityFloorTile');if(![...select.options].some(o=>o.value===value)){const o=document.createElement('option');o.value=value;o.textContent=x+','+y+' · chosen ground';select.append(o);}select.value=value;selectFloor();};
 return{reset(){job++;source=floor=candidate=draft=null;mask.fill(0);host.hidden=true;},async open(){const token=++job,c=current(),map=original.maps.find(m=>m.id===c.mapId),tile=map.layers.ground[c.y*map.width+c.x];source=floor=candidate=draft=null;mask.fill(0);host.hidden=false;$('#authorityFloorX').value=c.x;$('#authorityFloorY').value=c.y;$('#authorityUseSplit').disabled=true;$('#authorityFloorTile').innerHTML='<option value="">Choose the floor beneath the selected pixels…</option>'+map.layers.ground.map((t,i)=>t&&Math.abs(i%map.width-c.x)<=2&&Math.abs(Math.floor(i/map.width)-c.y)<=2&&i!==c.y*map.width+c.x?`<option value="i${i}">${i%map.width},${Math.floor(i/map.width)} · nearby ground</option>`:'').join('');if(!tile||!api.image){api.toast('Ground artwork is unavailable.');return;}try{const data=await read(tile);if(token!==job)return;source=data;update();}catch(e){if(token===job)api.toast('Could not load ground: '+e.message);}}};
}
export const groundSplitMarkup=`<button id="authoritySeparateGround" type="button">Separate foreground pixels from ground…</button><section id="authoritySplitter" hidden><p>Paint the pixels that should cover the player (pink). Choose nearby ground to fill beneath those pixels. Unselected pixels, collision, exits and other objects stay as saved. No floor is guessed.</p><canvas id="authorityPixelMask" width="256" height="256" style="display:block;width:256px;max-width:100%;image-rendering:pixelated;touch-action:none"></canvas><label><input type="checkbox" id="authorityErasePixels"> Erase selection</label><button id="authorityClearPixels" type="button">Clear selection</button><button id="authorityAllPixels" type="button">Select entire tile</button><label>Floor beneath foreground<select id="authorityFloorTile"></select></label><canvas id="authorityFloorPreview" width="64" height="64" style="image-rendering:pixelated"></canvas><p>Or choose ground elsewhere on this map:</p><label>Floor X<input id="authorityFloorX" type="number" min="0"></label><label>Floor Y<input id="authorityFloorY" type="number" min="0"></label><button id="authorityFloorCoordinates" type="button">Use ground at these coordinates</button><p id="authoritySplitCount"></p><button id="authorityPreviewSplit" type="button">Preview separated tile</button><button id="authorityUseSplit" type="button" disabled>Use this separation for this tile</button></section>`;
